INSERT INTO "dimension" VALUES('aislamiento','Aislamiento social');
INSERT INTO "dimension" VALUES('funcional','Deterioro funcional');
INSERT INTO "dimension" VALUES('medicacion','Medicamentos y tratamientos');
INSERT INTO "dimension" VALUES('emocional_cognitiva','Salud emocional y cognitiva');
INSERT INTO "dimension" VALUES('seguridad','Seguridad y emergencias');
INSERT INTO "indicator" VALUES('soledad_percibida','aislamiento','category','["no", "a_veces", "frecuente"]','Sensación de soledad que la persona declara: no se siente sola, a veces o con frecuencia. No se deduce de vivir sola. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('contacto_social_24h','aislamiento','bool',NULL,'Verdadero si la persona conversó con alguien (familia, vecinos, amistades) en el período. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('menor_contacto_habitual','aislamiento','bool',NULL,'Verdadero si la persona refiere tener menos contacto con otras personas que lo habitual para ella. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('apoyo_disponible','aislamiento','bool',NULL,'Verdadero si la persona declara contar con alguien que puede ayudarla si lo necesita; falso si refiere haber perdido ese apoyo. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('cambio_autonomia','funcional','category','["sin_cambio", "mejora", "empeora"]','Cambio reportado en su autonomía para las actividades cotidianas respecto de su situación habitual: sin cambio, mejora o empeora. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('dificultad_puntual_reportada','funcional','bool',NULL,'Verdadero si la persona refiere una dificultad puntual en una actividad cotidiana, sin que se haya confirmado un cambio en su autonomía. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('actividad_afectada','funcional','list','["desplazarse", "asearse", "vestirse", "alimentarse", "comprar", "preparar_alimentos", "otra"]','Actividades cotidianas en las que refiere dificultad; lista vacía si no menciona ninguna. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('adherencia_reportada','medicacion','category','["completa", "parcial", "ninguna", "no_aplica"]','Cumplimiento reportado de sus medicamentos: completa, parcial o ninguna; no_aplica si no tiene tratamiento. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('barrera_tratamiento','medicacion','list','["olvido", "acceso", "molestia_reportada", "otra"]','Motivos que la persona da para no seguir su tratamiento (olvido, no conseguir los medicamentos, molestias, otro); lista vacía si no reporta barrera. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('animo_reportado','emocional_cognitiva','category','["bien", "regular", "mal"]','Estado de ánimo que la persona declara: bien, regular o mal. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('tristeza_reportada','emocional_cognitiva','category','["no", "ocasional", "persistente"]','Tristeza que la persona declara sentir: no, ocasional o persistente. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('confusion_nueva_reportada','emocional_cognitiva','bool',NULL,'Verdadero solo si la persona declara explícitamente confusión nueva; no es un diagnóstico ni se infiere de una frase confusa. Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('caida_reportada','seguridad','bool',NULL,'Verdadero si la persona refiere haberse caído en el período (por sí sola, sin que se infiera una lesión). Período: desde la última conversación, máximo 24 horas.',0);
INSERT INTO "indicator" VALUES('lesion_reportada','seguridad','bool',NULL,'Verdadero si la persona refiere una lesión, golpe o dolor intenso asociado a un incidente reciente. Período: desde la última conversación, máximo 24 horas.',1);
INSERT INTO "indicator" VALUES('sintoma_agudo_protocolo','seguridad','bool',NULL,'Verdadero si refiere un síntoma agudo contemplado en el guion de emergencia (por ejemplo dolor de pecho, falta de aire o desmayo). Período: desde la última conversación, máximo 24 horas.',1);
INSERT INTO "indicator" VALUES('necesita_ayuda_inmediata','seguridad','bool',NULL,'Verdadero solo si la persona pide ayuda de forma explícita ahora o dice necesitar que alguien vaya a verla de inmediato. Período: desde la última conversación, máximo 24 horas.',1);
INSERT INTO "message" VALUES(1,1,1,'asistente',NULL,'Hola Rosa, buen día. Soy el asistente automático del programa de acompañamiento. ¿Estoy hablando con Rosa?');
INSERT INTO "message" VALUES(2,1,2,'persona',NULL,'Sí, con Rosa, dígame.');
INSERT INTO "message" VALUES(3,1,3,'asistente','soledad_percibida','Muchas gracias. Quiero saber cómo ha estado desde la última vez que conversamos. ¿Ha sentido soledad desde ayer?');
INSERT INTO "message" VALUES(4,1,4,'persona',NULL,'No, gracias a Dios, tengo con quien conversar.');
INSERT INTO "message" VALUES(5,1,5,'asistente','contacto_social_24h','¿Alguien la o lo pasó a ver o llamó desde ayer?');
INSERT INTO "message" VALUES(6,1,6,'persona',NULL,'Sí, conversé con unos amigos en la tarde.');
INSERT INTO "message" VALUES(7,1,7,'asistente','apoyo_disponible','¿Cuenta con alguien que la o lo apoye si hace falta?');
INSERT INTO "message" VALUES(8,1,8,'persona',NULL,'Sí, mi familia está pendiente.');
INSERT INTO "message" VALUES(9,1,9,'asistente','cambio_autonomia','¿Ha notado algún cambio en cómo se las arregla sola o solo en el día a día?');
INSERT INTO "message" VALUES(10,1,10,'persona',NULL,'Nada ha cambiado, hago mis cosas como siempre.');
INSERT INTO "message" VALUES(11,1,11,'asistente','adherencia_reportada','¿Cómo va con sus remedios, los ha tomado?');
INSERT INTO "message" VALUES(12,1,12,'persona',NULL,'Claro, me los tomé con el desayuno.');
INSERT INTO "message" VALUES(13,1,13,'asistente','animo_reportado','¿Cómo ha estado de ánimo hoy?');
INSERT INTO "message" VALUES(14,1,14,'persona',NULL,'Bien, gracias, amanecí con buen ánimo.');
INSERT INTO "message" VALUES(15,1,15,'asistente','confusion_nueva_reportada','¿Le ha pasado de sentirse confundida o confundido de una forma distinta a lo normal?');
INSERT INTO "message" VALUES(16,1,16,'persona',NULL,'No, nada de eso.');
INSERT INTO "message" VALUES(17,1,17,'asistente','caida_reportada','¿Se ha caído desde ayer?');
INSERT INTO "message" VALUES(18,1,18,'persona',NULL,'No, gracias a Dios, no me he caído.');
INSERT INTO "message" VALUES(19,1,19,'asistente','necesita_ayuda_inmediata','¿Necesita que alguien vaya a verla o verlo ahora?');
INSERT INTO "message" VALUES(20,1,20,'persona',NULL,'No, ahora no, gracias.');
INSERT INTO "message" VALUES(21,1,21,'asistente',NULL,'Gracias por conversar conmigo, Rosa. Cualquier cosa me avisa. Hasta mañana.');
INSERT INTO "message" VALUES(22,2,1,'asistente',NULL,'Buenos días Rosa, le llama el asistente automático de seguimiento. ¿Me confirma que usted es Rosa?');
INSERT INTO "message" VALUES(23,2,2,'persona',NULL,'Sí, aquí estoy, buenos días.');
INSERT INTO "message" VALUES(24,2,3,'asistente','soledad_percibida','Perfecto, gracias. Serán unas preguntas breves sobre las últimas horas. ¿Cómo se ha sentido de compañía en las últimas 24 horas?');
INSERT INTO "message" VALUES(25,2,4,'persona',NULL,'No, con mi gente cerca estoy en paz.');
INSERT INTO "message" VALUES(26,2,5,'asistente','contacto_social_24h','¿Conversó con alguien desde ayer?');
INSERT INTO "message" VALUES(27,2,6,'persona',NULL,'Sí, me llamó mi hijo anoche.');
INSERT INTO "message" VALUES(28,2,7,'asistente','apoyo_disponible','Si necesitara ayuda, ¿tiene alguien a quien recurrir?');
